#include <bits/stdc++.h>
using namespace std;
struct E{int f,t,a,c;vector<int>I,O;};struct N{int p;vector<int>r;int par,ei;bool live;int depth;};
int main(int ac,char**av){ifstream f(av[1]);int m,np,ne,ni,ng;f>>m>>np>>ne>>ni>>ng;int d=m*5;assert(f&&m>0);vector<char>init(np);for(int j=0,p;j<ni;j++){f>>p;init.at(p)=1;}vector<pair<int,vector<int>>>goals;for(int j=0,p;j<ng;j++){f>>p;vector<int>r(d);for(auto&x:r)f>>x;goals.push_back({p,r});}vector<E>es(ne);vector<vector<int>>inc(np);for(int j=0;j<ne;j++){auto&e=es[j];f>>e.f>>e.t>>e.a>>e.c;e.I.resize(d);e.O.resize(m);for(auto&x:e.I)f>>x;for(auto&x:e.O)f>>x;assert(f&&e.c>=0&&e.c<=4);inc[e.t].push_back(j);}size_t limit=ac>2?stoull(av[2]):1000000;vector<N>ns;vector<vector<int>>B(np);size_t retired=0,cmp=0;int hit=-1;using Item=tuple<long long,int,int>;priority_queue<Item,vector<Item>,greater<Item>>todo;auto le=[&](const vector<int>&a,const vector<int>&b){cmp++;for(int i=0;i<d;i++)if(a[i]>b[i])return false;return true;};auto add=[&](int p,const vector<int>&r,int par,int ei){auto&v=B[p];for(int id:v)if(ns[id].live&&le(ns[id].r,r))return;for(int id:v)if(ns[id].live&&le(r,ns[id].r)){ns[id].live=false;retired++;if(ns[id].par>=0)vector<int>().swap(ns[id].r);}if(v.size()>32){vector<int>w;for(int id:v)if(ns[id].live)w.push_back(id);v.swap(w);}int id=ns.size();int dep=par>=0?ns[par].depth+1:0;ns.push_back({p,r,par,ei,true,dep});v.push_back(id);long long score=accumulate(r.begin(),r.end(),0LL);todo.emplace(score,dep,id);if(init[p]&&all_of(r.begin(),r.end(),[](int x){return x==0;}))hit=id;};for(auto&[p,r]:goals)add(p,r,-1,-1);int depth=0;size_t pops=0;
while(!todo.empty()&&hit<0){auto [score,dep,k]=todo.top();todo.pop();if(!ns[k].live)continue;pops++;depth=max(depth,dep);if(pops%100000==0)cerr<<"pops "<<pops<<" labels "<<ns.size()<<" live "<<ns.size()-retired<<" queue "<<todo.size()<<" cost "<<score<<" depth "<<dep<<" comparisons "<<cmp<<"\n";int p=ns[k].p;auto r=ns[k].r;for(int ei:inc[p]){auto&e=es[ei];vector<int>v(d);for(int z=0;z<m;z++){int o=5*z,c=e.c;v[o]=e.I[o]+max({0,r[o]-e.O[z],c<4?r[o+c+1]:0});for(int j=1;j<5;j++)v[o+j]=e.I[o+j]+(j+c<5?r[o+j+c]:0);for(int j=0;j<4;j++)assert(v[o+j]>=v[o+j+1]);if(v[o]>1000000){cout<<"status RESOURCE_LIMIT\n";return 0;}}add(e.f,v,k,ei);if(ns.size()>=limit){cout<<"status CAP labels "<<ns.size()<<" depth "<<depth<<" live "<<ns.size()-retired<<"\n";return 0;}if(hit>=0)break;}}
if(hit<0){cout<<"status EXHAUSTED_NO_ZERO_INITIAL labels "<<ns.size()<<" live "<<ns.size()-retired<<" depth "<<depth<<"\n";if(ac>3){ofstream o(av[3]);o<<m<<" "<<np<<" "<<ns.size()-retired<<"\n";for(auto&n:ns)if(n.live){o<<n.p;for(auto x:n.r)o<<" "<<x;o<<"\n";}}return 0;}
cout<<"status AGE_PETRI_WITNESS labels "<<ns.size()<<" depth "<<depth<<"\n";int u=hit;cout<<"start "<<ns[u].p<<"\n";vector<int>mark(d);while(ns[u].par>=0){auto&n=ns[u];auto&e=es[n.ei];cout<<"EDGE "<<n.ei<<" "<<e.f<<" "<<e.t<<" "<<e.a;for(auto x:mark)cout<<" "<<x;cout<<"\n";
for(int z=0;z<m;z++){int o=5*z;vector<int>ages(5),need(5);for(int j=0;j<5;j++){ages[j]=mark[o+j]-(j<4?mark[o+j+1]:0);need[j]=e.I[o+j]-(j<4?e.I[o+j+1]:0);}for(int j=4;j>=0;j--)for(int k=j;k<5&&need[j];k++){int t=min(need[j],ages[k]);need[j]-=t;ages[k]-=t;}assert(all_of(need.begin(),need.end(),[](int x){return x==0;}));vector<int>after(5);for(int j=0;j<5;j++)after[min(4,j+e.c)]+=ages[j];after[e.c]+=e.O[z];for(int j=3;j>=0;j--)after[j]+=after[j+1];for(int j=0;j<5;j++)mark[o+j]=after[j];}
u=n.par;}cout<<"goal "<<ns[u].p;for(auto x:mark)cout<<" "<<x;cout<<"\n";assert(le(ns[u].r,mark));}
